# -*- coding: utf-8 -*-
"""Рядок 153 (5): модель LM Studio на «фото речі від жінки» (рядок 152) — рід і рамка речі на 20 фото. Набір — вибірка жнив v2 з фото
в git, сід 153: останні 2 речі кожної групи слота (перші 4 міряє vymir_modelei_153.py), той самий для всіх моделей. Рід — проти групи
слота каталогу; рамка — IoU ≥ 0.5 з рамкою маски жнив (`маска_речі`: ATR → SAM → запасна; без ATR — `маска_без_людини`), xyxy або yxyx
(Gemini й Gemma пишуть y першим). Фото — у %TEMP% латиницею: cv2 на Windows не читає кирилиці в шляху (урок `маска_sam`). Промпт
мінімальний — свого рядок 152 ще не дав; с/фото — лише модель. `--сам`: еталон замість моделі, мусить бути 100 % (інакше rc 1). ТОЧКА ВІДЛІКУ 24.09: qwen3-vl-8b-instruct — рамка 14/20, рід 13/20, 0.5–1.2 с/фото. Еталон рамки — «ATR 7 · SAM 13»; змінювався двічі за день, і числа різних еталонів НЕ порівнювати: поки :8000 лежав, він був «ATR + запасна» і давав 12/20; з живим SAM став «ATR 10 · SAM 10» і 13/20; а коли ATR перестав віддавати клаптик на кадрі без людини (`_покриття_без_людини`), вісім кадрів пішли в SAM, еталонна рамка почала обводити річ ЦІЛКОМ — і рамка стала 14/20 при тому самому роді. Саме це й було написане в докстрінгу `маска_речі` як передбачення. СТЕЛЯ «РОДУ» НИЗЬКА — читала всі 20 відповідей очима (24.09). З 7 промахів: на 3 у кадрі кілька речей і модель назвала іншу (гольф із джинсами → «низ», топ із сумкою в руці → «сумка», шапка з пуховиком → «верх») — це фото крамниці, а рядок 152 обіцяє фото ОДНІЄЇ речі від жінки; ще 3 — тонка межа словом при правильній рамці (куртка «верх» замість «верхній_шар» при IoU 0.93, пальто «сукня» при 0.90, бант у волоссі «головний_убір» замість «прикраси»); 1 — сам каталог дивний (крамниця зве «Шорти з батиста», слот «пояс»). Тобто бездоганна модель узяла б тут близько 16–17/20, не 20/20, і різниця в одиницю-дві між кандидатами нічого не означає. І ЦЕ ПРАВИЛО ВЖЕ СПРАЦЮВАЛО ПРОТИ КАНДИДАТА, не лише на папері: gemma-4-12b-it-qat дала рамку 14/20 і рід 14/20 за 0.9 с/фото — рамка нарівно, рід на одиницю вище, — і ця одиниця НЕ рахується виграшем, бо лежить усередині тих самих 3–4 промахів, які тут не про модель (кілька речей у кадрі, тонка межа словом, дивний запис каталогу). На цій пробі переможця нема. І ЩЕ ОДНА ПАСТКА, ЯКА КОШТУВАЛА Б ХИБНОГО ВИСНОВКУ (24.09): якщо модель ДУМАЄ (`capabilities.reasoning.default: on` — у Qwen3.5-9B так, у qwen3-vl і gemma нема), думка йде в `reasoning_content`, а `content` лишається ПОРОЖНІЙ, поки бюджет не вичерпано — на 300 токенах цієї проби чесний результат такої моделі був би 0/20, тобто число про бюджет, а не про модель. З семи випробуваних способів вимикає тільки `"reasoning_effort": "none"` у тілі запиту: `/no_think` змушує думати ВДВІЧІ більше (шаблон цього токена не знає), `enable_thinking`, `chat_template_kwargs`, `thinking.type=disabled` і `reasoning_effort=minimal` не роблять нічого, префікс `<think></think>` дає HTTP 400, а в `lms load` прапорця нема. І ціна помилки тут виміряна: Qwen3.5-9B Q8_0 з думанням дала рамку 14/20, рід 15/20 (найкращий рід з усіх) — але 50.8 с/фото, ×50 проти поточної; та сама модель БЕЗ думання — 1.1 с/фото, але рамка 13/20 і рід 12/20, тобто ГІРШЕ за поточну на обох. Думання тут купувало точність за п'ятдесятикратний час, і в жодному з двох станів вона не виграє. І ПАСТКА ВСЕРЕДИНІ ПАСТКИ, яка коштувала 32 хвилин прогону (24.09): `reasoning_effort: "none"` — властивість ЗАВАНТАЖЕННЯ, а не моделі. Той самий файл Q4_K_M, піднятий `lms load qwen3.5-9b@q4_k_m` (голим іменем варіанта), перемикача не слухається — думка 695 символів і з ним, і без; піднятий `lms load qwen/qwen3.5-9b` (ключем каталогу) — глушиться дочиста, 0 символів за 0.2 с. І проби при цьому НЕ падають, а дають правдоподібні числа: (3) видала «намір 3/12», що є рівно кількістю текстів з очікуванням `conventional`, тобто лічильник рахував ЗАПАСНЕ значення розбору; (1) і (5) — 0/232 і 1/20 самими збоями. Тому перед кожним виміром думаючої моделі — контроль перемикача на цьому самому завантаженні (дві відповіді на одне питання, з полем і без), і лише тоді проби. Q4_K_M із робочим перемикачем: рамка 12/20, рід 12/20, 0.8 с/фото — на цій пробі вона ГІРША за поточну (14/20 · 13/20), хоч на жнивах виграє."""
import collections, json, os, random, shutil, sys, tempfile, time, urllib.request
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np, жнива_v2 as Ж
мод, сам = next((a for a in sys.argv[1:] if not a.startswith("--")), "qwen3-vl-8b-instruct"), "--сам" in sys.argv
if not сам:
    try: urllib.request.urlopen("http://127.0.0.1:1234/v1/models", timeout=10)
    except Exception as e: sys.exit("LM Studio не відповідає (%s) — модель «%s» не виміряти" % (type(e).__name__, мод))
ТЕКА, гр, лік, збої = os.path.join(Ж.ТУТ, "аудит"), collections.defaultdict(list), collections.defaultdict(lambda: [0, 0]), collections.Counter()
for з in sorted(json.load(open(os.path.join(ТЕКА, "збагачення_v2_вибірка.json"), encoding="utf-8"))["речі"], key=lambda з: з["id"]):
    if з.get("поля") and os.path.exists(os.path.join(ТЕКА, з.get("фото_показу") or "-")): гр[Ж.група_слота(з["слот"])].append(з)
for г in гр: random.Random(153).shuffle(гр[г])
def iou(а, б):
    """IoU двох рамок xyxy у тисячних частках кадру; рамки без спільної площі або криві — 0."""
    ш, в = max(0, min(а[2], б[2]) - max(а[0], б[0])), max(0, min(а[3], б[3]) - max(а[1], б[1])); с = (а[2] - а[0]) * (а[3] - а[1]) + (б[2] - б[0]) * (б[3] - б[1]) - ш * в
    return ш * в / с if с > 0 else 0.0
РОДИ, т = sorted(гр), 0.0
ПРОМПТ = ('На фото — одна річ, яку жінка сфотографувала сама. Відповідай ЛИШЕ JSON без markdown: {"рід": "<одне з: %s>", "рамка": [x0, y0, x1, y1]} '
          '— рамка довкола самої речі в тисячних частках ширини й висоти кадру (0–1000).' % ", ".join(РОДИ))
речі = [з for г in РОДИ for з in гр[г][-2:]]
for н, з in enumerate(речі):
    шлях, г = os.path.join(tempfile.gettempdir(), "vymir153_%02d.jpg" % н), Ж.група_слота(з["слот"]); shutil.copyfile(os.path.join(ТЕКА, з["фото_показу"]), шлях)
    try: м, _, _, дж = Ж.маска_речі(шлях, з["слот"])
    except Exception as e: (м, _, _), дж = Ж.маска_без_людини(шлях), "запасна (ATR: %s)" % type(e).__name__
    ys, xs = np.nonzero(м) if м is not None else ([], []); лік["еталон рамки: " + дж.split(" (")[0]][1] += 1
    ет = [xs.min() * 1000 / м.shape[1], ys.min() * 1000 / м.shape[0], (xs.max() + 1) * 1000 / м.shape[1], (ys.max() + 1) * 1000 / м.shape[0]] if len(xs) else None
    try: т1 = time.time(); від = {"рід": г, "рамка": ет} if сам else Ж._запит(мод, ПРОМПТ, [Ж._b64(Ж._фото_1024(шлях), сторона=1024)], токенів=300)
    except Exception as e: від = {}; збої[type(e).__name__] += 1
    т += time.time() - т1; р = від.get("рамка") if isinstance(від.get("рамка"), list) and len(від["рамка"]) == 4 and all(isinstance(x, (int, float)) for x in від["рамка"]) else [0] * 4
    лік["рід"][0] += str(від.get("рід") or "").strip().lower() == г; лік["рід"][1] += 1
    if ет: лік["рамка IoU>=0.5"][0] += max(iou(р, ет), iou([р[1], р[0], р[3], р[2]], ет)) >= 0.5; лік["рамка IoU>=0.5"][1] += 1
print("(5) %d фото · модель %s%s · %.1f с/фото · збоїв %d%s" % (len(речі), мод, " --сам (еталон замість моделі)" if сам else "", т / len(речі),
      sum(збої.values()), " %s" % dict(збої) if збої else ""))
print("    " + " · ".join(("%s %d/%d" % (к, *в)) if not к.startswith("еталон") else "%s %d" % (к, в[1]) for к, в in sorted(лік.items())))
sys.exit(1 if сам and any(в[0] != в[1] for к, в in лік.items() if not к.startswith("еталон")) else 0)
